"""Yedegi hedef diske **yeni bir bolum yerlesimiyle** geri yukleme.

## Neden

Duz geri yukleme (`clone.restore`) yedegi bayt bayt yazar: hedef yedekten
kucukse reddedilir, buyukse fazlasi bos kalir ve GPT'nin yedek basligi eski
disk sonunda kalir. DiskGenius'un "Bolumleri Yonet" dugmesi ise yedekteki
bolumleri hedef diske **yeniden yerlestirir**: bolumler buyutulup
kucultulebilir, kaydirilabilir; dosya sistemi yeni boyuta getirilir.

## Yerlesim

`RestoreLayout` yedekteki her bolum icin eski ve yeni (baslangic, sektor)
ciftini ve dosya sisteminin sinirlarini tasir. Sinirlar `resize.fs_resize_info`
ile **yedegin icinden** okunur:

  * FAT / exFAT / NTFS: en az = verinin gerektirdigi, en cok = FS siniri.
  * Dosya sistemi tanimlanamayan bolum ("ham"): **kucultulmez** (icerigini
    bilmiyoruz; BitLocker da ham gorunur), buyutulebilir ama eklenen alan
    kullanilmaz.
  * Boyutlandirilamayan dosya sistemi (ext vb.): boyut sabittir, yer degisir.

Genisletilmis MBR bolumu kullanicinin duzenledigi bir oge degildir; icindeki
mantiksal bolumlere gore her seferinde yeniden hesaplanir.

## Uygulama sirasi (`restore_with_layout`)

  1. Bolumlerden onceki alan (MBR onyukleme kodu, GRUB'un MBR boslugu)
     yedekten kopyalanir.
  2. Her bolum yeni yerine kopyalanir. **Kucultulen** bolumde yedek salt
     okunur oldugu icin dosya sistemi bellekteki bir yazma katmani
     (`_Overlay`) uzerinde kucultulur, sonra yeni boyut kadari yazilir.
  3. Bolum tablosu hedefin boyutuna gore yeniden yazilir (GPT yedek basligi
     yeni disk sonuna gider).
  4. **Buyutulen** bolumde dosya sistemi hedef uzerinde buyutulur; yalnizca
     yeri degisen bolumde onyukleme sektorundeki bolum konumu duzeltilir.
"""
from __future__ import annotations

import copy
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional

from .clone import CloneError, DubImage, read_backup_info
from .gpt import GPTTable
from .image import BlockDevice, PartitionView
from .mbr import MBRTable
from .ptable import (ALIGN_BYTES, MBR_EXTENDED_TYPES, Partition,
                     PartitionTable, human_size)
from .resize import (_fs_resize, _patch_partition_offset, fs_resize_info)
from ..i18n import tr

Progress = Optional[Callable[[str, int], None]]

FS_KINDS = ("fat", "exfat", "ntfs")      # saf Python'da boyutlandirilabilenler
COPY_CHUNK = 4 * 1024 * 1024
OVERLAY_CHUNK = 64 * 1024


class RestorePlanError(Exception):
    pass


# --------------------------------------------------------------------------
#  Yerlesim
# --------------------------------------------------------------------------
@dataclass
class LayoutPart:
    """Yedekteki bir bolumun eski ve yeni yeri."""
    part: Partition                  # yedekteki tanim (tip, GUID, ad)
    old_start: int
    old_count: int
    new_start: int
    new_count: int
    kind: str = "raw"                # FsResizeInfo.kind
    fs_type: str = ""
    label: str = ""
    min_count: int = 1
    max_count: int = 0               # 0 = sinirsiz
    note: str = ""

    @property
    def index(self) -> int:
        return self.part.index

    @property
    def logical(self) -> bool:
        return self.part.logical

    @property
    def resizable(self) -> bool:
        """Boyutu degistirilebilir mi (ham bolum yalnizca buyuyebilir)."""
        return self.kind in FS_KINDS or self.kind == "raw"

    @property
    def fs_resizable(self) -> bool:
        return self.kind in FS_KINDS

    @property
    def moves(self) -> bool:
        return self.new_start != self.old_start

    @property
    def grows(self) -> bool:
        return self.new_count > self.old_count

    @property
    def shrinks(self) -> bool:
        return self.new_count < self.old_count

    @property
    def new_end(self) -> int:
        return self.new_start + self.new_count - 1

    def clamp(self, count: int) -> int:
        count = max(self.min_count, count)
        if self.max_count:
            count = min(self.max_count, count)
        return count

    def as_partition(self) -> Partition:
        """Yeni yerindeki bolum (harita ve tablo icin kopya)."""
        part = copy.copy(self.part)
        part.start_lba = self.new_start
        part.sector_count = self.new_count
        part.fs_type = self.fs_type
        part.fs_label = self.label
        if part.logical:
            part.ebr_lba = 0          # EBR yeni baslangica gore hesaplanir
        return part


@dataclass
class RestoreLayout:
    """Yedegin hedef diske yerlesim plani."""
    scheme: str                       # 'gpt' | 'mbr'
    sector_size: int
    source_sectors: int
    target_sectors: int
    parts: List[LayoutPart] = field(default_factory=list)
    extended: Optional[Partition] = None      # MBR genisletilmis kapsayici
    gpt_first_usable: int = 0
    gpt_entry_sectors: int = 32

    # -- sinirlar ------------------------------------------------------------
    @property
    def align(self) -> int:
        return max(1, ALIGN_BYTES // self.sector_size)

    def first_usable(self) -> int:
        if self.scheme == "gpt":
            return max(self.gpt_first_usable, 2 + self.gpt_entry_sectors)
        return 1

    def last_usable(self) -> int:
        if self.scheme == "gpt":
            return self.target_sectors - 2 - self.gpt_entry_sectors
        return self.target_sectors - 1

    def align_up(self, lba: int) -> int:
        return -(-lba // self.align) * self.align

    def align_down(self, lba: int) -> int:
        return (lba // self.align) * self.align

    def sorted_parts(self) -> List[LayoutPart]:
        return sorted(self.parts, key=lambda p: (p.new_start, p.index))

    def get(self, index: int) -> LayoutPart:
        for part in self.parts:
            if part.index == index:
                return part
        raise RestorePlanError(tr("{} numarali bolum yok", index))

    def _reserved_before(self, part: LayoutPart) -> int:
        """Bolumun onunde ayrilmasi gereken sektor (mantiksalda EBR)."""
        return self.align if part.logical else 0

    # -- durum ---------------------------------------------------------------
    @property
    def is_identity(self) -> bool:
        """Yerlesim yedektekiyle ayni ve hedef ayni boyutta mi?"""
        return (self.target_sectors == self.source_sectors
                and all(not p.moves and p.new_count == p.old_count
                        for p in self.parts))

    @property
    def changed(self) -> bool:
        return any(p.moves or p.new_count != p.old_count for p in self.parts)

    def required_sectors(self) -> int:
        """En siki yerlesimde hedefin en az kac sektor olmasi gerektigi."""
        trial = self.copy()
        trial.target_sectors = 1 << 62
        trial._pack(0.0)
        end = max((p.new_end for p in trial.parts), default=0)
        tail = (2 + self.gpt_entry_sectors) if self.scheme == "gpt" else 1
        return end + tail

    def validate(self) -> str:
        """Yerlesimdeki ilk hata ("" = gecerli)."""
        if self.target_sectors <= 0:
            return tr("Hedef boyutu bilinmiyor")
        previous_end = self.first_usable() - 1
        for part in self.sorted_parts():
            if part.new_count <= 0:
                return tr("Bolum {}: boyut sifir olamaz", part.index)
            if part.new_count < part.min_count:
                return tr("Bolum {}: {} altina inemez (veri kaybi olurdu)",
                          part.index,
                          human_size(part.min_count * self.sector_size))
            if part.max_count and part.new_count > part.max_count:
                return tr("Bolum {}: dosya sistemi en fazla {} olabilir",
                          part.index,
                          human_size(part.max_count * self.sector_size))
            if not part.resizable and part.new_count != part.old_count:
                return tr("Bolum {}: {} boyutlandirilamaz",
                          part.index, part.fs_type or tr("bu dosya sistemi"))
            if part.new_start - self._reserved_before(part) <= previous_end:
                return tr("Bolum {} onceki bolumle cakisiyor", part.index)
            if part.new_end > self.last_usable():
                return tr("Bolum {} hedef diskin sonunu asiyor "
                          "(hedef {}, gereken en az {})", part.index,
                          human_size(self.target_sectors * self.sector_size),
                          human_size(self.required_sectors()
                                     * self.sector_size))
            previous_end = part.new_end
        if self.scheme == "mbr":
            primaries = [p for p in self.parts if not p.logical]
            if len(primaries) + (1 if self.extended is not None else 0) > 4:
                return tr("MBR en fazla 4 birincil bolum destekler")
            if self.extended is not None:
                logicals = [p for p in self.sorted_parts() if p.logical]
                ext_start = logicals[0].new_start - self.align
                ext_end = logicals[-1].new_end
                for p in primaries:
                    if not (p.new_end < ext_start or p.new_start > ext_end):
                        return tr("Bolum {} mantiksal bolumlerin arasina "
                                  "giremez", p.index)
        return ""

    # -- stratejiler ---------------------------------------------------------
    def copy(self) -> "RestoreLayout":
        clone = copy.copy(self)
        clone.parts = [copy.copy(p) for p in self.parts]
        return clone

    def reset(self) -> None:
        """Yedekteki yerlesime dondurur."""
        for part in self.parts:
            part.new_start, part.new_count = part.old_start, part.old_count

    def retarget(self, target_sectors: int) -> None:
        """Hedef boyutunu degistirir ve yerlesimi ona uydurur.

        Yedekteki yerlesim sigiyorsa oldugu gibi kalir (fazla alan bos kalir);
        sigmiyorsa bolumler **gerektigi kadar** kucultulur.
        """
        self.target_sectors = target_sectors
        self.reset()
        if self.validate():
            self.fit(expand=False)

    def fit(self, expand: bool = True) -> bool:
        """Bolumleri orantili olarak hedefe yayar.

        `expand=False` yalnizca sigdirmak icin kucultur; `True` bos alani da
        bolumlere dagitir. Sigmiyorsa False doner ve yerlesim degismez.
        """
        low, high = 0.0, 1.0
        if expand:
            high = max(1.0, 2.0 * self.target_sectors
                       / max(1, self.source_sectors))
        saved = [(p.new_start, p.new_count) for p in self.parts]
        if not self._pack(0.0):
            for part, (start, count) in zip(self.parts, saved):
                part.new_start, part.new_count = start, count
            return False
        if self._pack(high):
            return True
        for _ in range(48):
            middle = (low + high) / 2
            if self._pack(middle):
                low = middle
            else:
                high = middle
        self._pack(low)
        return True

    def extend_last(self) -> bool:
        """Diskte en sondaki boyutlandirilabilir bolumu bos alana yayar."""
        ordered = self.sorted_parts()
        for part in reversed(ordered):
            if not part.resizable:
                continue
            after = [p for p in ordered if p.new_start > part.new_start]
            upper = (min(p.new_start - self._reserved_before(p)
                         for p in after) - 1 if after
                     else self.last_usable())
            count = upper - part.new_start + 1
            if part.max_count:
                count = min(count, part.max_count)
            if count < part.min_count:
                return False
            part.new_count = count
            return True
        return False

    def _pack(self, factor: float) -> bool:
        """Bolumleri eski sirasiyla arka arkaya dizer; boyut = eski * factor."""
        cursor = self.first_usable()
        first = min((p.old_start - self._reserved_before(p)
                     for p in self.parts), default=cursor)
        cursor = self.align_up(max(cursor, min(first, self.align)))
        for part in sorted(self.parts, key=lambda p: p.old_start):
            cursor += self._reserved_before(part)
            start = self.align_up(cursor)
            if part.resizable:
                count = part.clamp(self.align_down(int(part.old_count * factor)))
                if not part.fs_resizable:
                    count = max(count, part.old_count)
            else:
                count = part.old_count
            part.new_start, part.new_count = start, count
            cursor = start + count
        return cursor - 1 <= self.last_usable()

    def window(self, index: int) -> tuple:
        """Bolumun komsulari arasinda hareket edebilecegi (ilk, son) LBA."""
        part = self.get(index)
        ordered = self.sorted_parts()
        pos = ordered.index(part)
        lower = self.first_usable()
        if pos > 0:
            lower = ordered[pos - 1].new_end + 1
        lower += self._reserved_before(part)
        upper = self.last_usable()
        if pos + 1 < len(ordered):
            nxt = ordered[pos + 1]
            upper = nxt.new_start - self._reserved_before(nxt) - 1
        return lower, upper

    def partitions(self) -> List[Partition]:
        """Haritada gosterilecek bolumler (yeni yerlerinde)."""
        out = [p.as_partition() for p in self.sorted_parts()]
        extended = self._extended_partition()
        if extended is not None:
            out.append(extended)
        return out

    def _extended_partition(self) -> Optional[Partition]:
        if self.extended is None:
            return None
        logicals = [p for p in self.sorted_parts() if p.logical]
        if not logicals:
            return None
        ext = copy.copy(self.extended)
        ext.start_lba = logicals[0].new_start - self.align
        ext.sector_count = logicals[-1].new_end - ext.start_lba + 1
        return ext

    def summary(self) -> List[str]:
        """Degisen bolumlerin tek satirlik dokumu."""
        lines = []
        ss = self.sector_size
        for part in self.sorted_parts():
            if part.new_count != part.old_count:
                lines.append(tr("Bolum {}: {} -> {}", part.index,
                                human_size(part.old_count * ss),
                                human_size(part.new_count * ss)))
            elif part.moves:
                lines.append(tr("Bolum {}: yeri degisiyor", part.index))
        return lines


def build_layout(image: BlockDevice, table: PartitionTable) -> RestoreLayout:
    """Yedek goruntusunun tablosundan yerlesim cikarir (hedef = kaynak).

    Dosya sistemi sinirlari yedegin icinden okunur; NTFS'te `$Bitmap`
    taranir, yani buyuk yedekte birkac saniye surebilir — arka planda
    cagrilir.
    """
    from .fsdetect import detect

    layout = RestoreLayout(scheme=table.scheme,
                           sector_size=image.sector_size,
                           source_sectors=image.sector_count,
                           target_sectors=image.sector_count)
    if isinstance(table, GPTTable):
        layout.gpt_first_usable = table._first_usable
        layout.gpt_entry_sectors = table.entry_sectors
    for part in table.sorted_partitions():
        if not part.logical and part.scheme == "mbr" and \
                part.type_id in MBR_EXTENDED_TYPES:
            layout.extended = copy.copy(part)
            continue
        view = PartitionView(image, part.start_lba, part.sector_count)
        try:
            found = detect(view)
            fs_type, label = found.fs_type, found.label
        except Exception:                             # noqa: BLE001
            fs_type, label = "", ""
        info = fs_resize_info(view, fs_type)
        item = LayoutPart(part=copy.copy(part), old_start=part.start_lba,
                          old_count=part.sector_count,
                          new_start=part.start_lba,
                          new_count=part.sector_count, kind=info.kind,
                          fs_type=fs_type, label=label, note=info.note)
        if info.kind in FS_KINDS:
            item.min_count = max(1, info.min_sectors)
            item.max_count = info.max_sectors
        elif info.kind == "raw":
            item.min_count = part.sector_count   # icerigi bilinmiyor
        else:
            item.min_count = item.max_count = part.sector_count
        layout.parts.append(item)
    return layout


def _read_table(device: BlockDevice) -> Optional[PartitionTable]:
    if GPTTable.is_present(device):
        return GPTTable.read(device)
    if MBRTable.is_present(device):
        return MBRTable.read(device)
    return None


def read_layout(src_path: str) -> Optional[RestoreLayout]:
    """`.dub` yedeginin yerlesimi; bolum tablosu yoksa None."""
    image = DubImage(src_path)
    try:
        table = _read_table(image)
        if table is None or not table.partitions:
            return None
        return build_layout(image, table)
    finally:
        image.close()


# --------------------------------------------------------------------------
#  Bellekte yazma katmani
# --------------------------------------------------------------------------
class _Overlay(BlockDevice):
    """Salt okunur bir aygitin ustunde bellekte duran yazma katmani.

    Kucultme, dosya sisteminin meta verisini (FAT/bitmap, NTFS'te sondan
    tasinan kumeler) yeniden yazar. Yedek dosyasi salt okunurdur; yazilar
    burada tutulur ve okumada yedegin uzerine bindirilir.
    """

    def __init__(self, base: BlockDevice):
        self._base = base
        self.sector_size = base.sector_size
        self._chunks: Dict[int, bytearray] = {}

    @property
    def sector_count(self) -> int:
        return self._base.sector_count

    @property
    def overlay_bytes(self) -> int:
        return len(self._chunks) * OVERLAY_CHUNK

    def _chunk(self, no: int) -> bytearray:
        data = self._chunks.get(no)
        if data is None:
            start = no * OVERLAY_CHUNK
            length = min(OVERLAY_CHUNK, self.size - start)
            data = bytearray(self._base.read(start, length))
            self._chunks[no] = data
        return data

    def read(self, offset: int, length: int) -> bytes:
        if offset + length > self.size:
            raise RestorePlanError(tr("Okuma bolum sinirini asiyor"))
        out = bytearray()
        pos = offset
        end = offset + length
        while pos < end:
            no, inner = divmod(pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, end - pos)
            data = self._chunks.get(no)
            if data is not None:
                out += data[inner:inner + n]
            else:
                # yazilmamis parcalar tek okumada birlestirilir
                run = n
                while pos + run < end and \
                        (pos + run) // OVERLAY_CHUNK not in self._chunks:
                    run += min(OVERLAY_CHUNK, end - pos - run)
                out += self._base.read(pos, run)
                n = run
            pos += n
        return bytes(out)

    def write(self, offset: int, data: bytes) -> None:
        if offset + len(data) > self.size:
            raise RestorePlanError(tr("Yazma bolum sinirini asiyor"))
        pos = 0
        while pos < len(data):
            no, inner = divmod(offset + pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, len(data) - pos)
            self._chunk(no)[inner:inner + n] = data[pos:pos + n]
            pos += n


# --------------------------------------------------------------------------
#  Uygulama
# --------------------------------------------------------------------------
def _copy_region(src: BlockDevice, src_lba: int, dst: BlockDevice,
                 dst_lba: int, count: int, tick: Callable[[int], None]) -> None:
    """Sektorleri kopyalar; bos (sifir) parcada hedef zaten sifirsa yazmaz."""
    ss = src.sector_size
    step = max(1, COPY_CHUNK // ss)
    pos = 0
    while pos < count:
        n = min(step, count - pos)
        data = src.read_sectors(src_lba + pos, n)
        if data.strip(b"\x00") or \
                dst.read_sectors(dst_lba + pos, n).strip(b"\x00"):
            dst.write_sectors(dst_lba + pos, data)
        pos += n
        tick(n)


def restore_with_layout(src_path: str, device: BlockDevice,
                        layout: RestoreLayout,
                        progress: Progress = None):
    """`.dub` disk yedegini `layout` yerlesimiyle `device` uzerine yazar."""
    def report(message: str, percent: int) -> None:
        if progress:
            progress(message, max(0, min(100, percent)))

    info = read_backup_info(src_path)
    if device.sector_count != layout.target_sectors:
        raise RestorePlanError(
            tr("Yerlesim baska bir hedef boyutu icin hazirlanmis; yenileyin"))
    if getattr(device, "readonly", False):
        raise CloneError(tr("Hedef salt okunur"))
    problem = layout.validate()
    if problem:
        raise RestorePlanError(problem)

    src = DubImage(src_path)
    try:
        if src.sector_size != device.sector_size:
            raise RestorePlanError(
                tr("Sektor boyutu farkli: yedek {}, hedef {}",
                   src.sector_size, device.sector_size))
        table = _read_table(src)
        if table is None or table.scheme != layout.scheme:
            raise RestorePlanError(tr("Yedegin bolum tablosu okunamadi"))

        ss = device.sector_size
        total = sum(min(p.old_count, p.new_count) for p in layout.parts) or 1
        done = [0]

        def tick(n: int) -> None:
            done[0] += n
            report(tr("Geri yukleniyor... {} / {}",
                      human_size(done[0] * ss), human_size(total * ss)),
                   5 + int(85 * done[0] / total))

        # 1) bolumlerden onceki alan: onyukleme kodu ve MBR boslugu
        report(tr("Geri yukleme baslatiliyor..."), 1)
        head = min([p.old_start - layout._reserved_before(p)
                    for p in layout.parts]
                   + [p.new_start - layout._reserved_before(p)
                      for p in layout.parts])
        _copy_region(src, 0, device, 0, max(1, head), lambda n: None)
        if layout.scheme == "mbr":
            # Hedefte eskiden GPT varsa yedek basligi diskin sonunda kalir;
            # bazi sistemler onu bulup MBR'yi yok sayar.
            last = device.sector_count - 1
            if device.read_sectors(last)[:8] == b"EFI PART":
                device.write_sectors(last, b"\x00" * ss)

        # 2) bolumler yeni yerlerine
        for part in layout.sorted_parts():
            source: BlockDevice = PartitionView(src, part.old_start,
                                                part.old_count)
            start = 0
            if part.shrinks and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi kucultuluyor...",
                          part.index), 5 + int(85 * done[0] / total))
                overlay = _Overlay(source)
                _fs_resize(overlay, 0, part.new_count, part.kind,
                           part.new_start, span=part.old_count)
                source = overlay
            _copy_region(source, start, device, part.new_start,
                         min(part.old_count, part.new_count), tick)

        # 3) bolum tablosu hedefin boyutuna gore
        report(tr("Bolum tablosu yaziliyor..."), 91)
        if layout.scheme == "gpt":
            new_table = GPTTable(device)
            new_table.disk_guid = table.disk_guid
            new_table.entry_count = table.entry_count
            new_table.entry_size = table.entry_size
            new_table._first_usable = layout.first_usable()
        else:
            new_table = MBRTable(device)
            new_table.bootcode = table.bootcode
            new_table.disk_signature = table.disk_signature
        new_table.partitions = layout.partitions()
        new_table.write()

        # 4) buyutme ve konum duzeltme hedefin uzerinde
        for part in layout.sorted_parts():
            if part.grows and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi buyutuluyor...",
                          part.index), 93)
                _fs_resize(device, part.new_start, part.new_count, part.kind,
                           part.new_start)
            elif part.moves and not part.shrinks:
                _patch_partition_offset(device, part.new_start,
                                        part.new_count)
        flush = getattr(device, "flush", None)
        if flush:
            flush()
    finally:
        src.close()
    report(tr("Tamamlandi"), 100)
    return info

toolu_01PiWs493AWumwBH9JNJA6Wj.content:
"""Yedegi hedef diske **yeni bir bolum yerlesimiyle** geri yukleme.

## Neden

Duz geri yukleme (`clone.restore`) yedegi bayt bayt yazar: hedef yedekten
kucukse reddedilir, buyukse fazlasi bos kalir ve GPT'nin yedek basligi eski
disk sonunda kalir. DiskGenius'un "Bolumleri Yonet" dugmesi ise yedekteki
bolumleri hedef diske **yeniden yerlestirir**: bolumler buyutulup
kucultulebilir, kaydirilabilir; dosya sistemi yeni boyuta getirilir.

## Yerlesim

`RestoreLayout` yedekteki her bolum icin eski ve yeni (baslangic, sektor)
ciftini ve dosya sisteminin sinirlarini tasir. Sinirlar `resize.fs_resize_info`
ile **yedegin icinden** okunur:

  * FAT / exFAT / NTFS: en az = verinin gerektirdigi, en cok = FS siniri.
  * Dosya sistemi tanimlanamayan bolum ("ham"): **kucultulmez** (icerigini
    bilmiyoruz; BitLocker da ham gorunur), buyutulebilir ama eklenen alan
    kullanilmaz.
  * Boyutlandirilamayan dosya sistemi (ext vb.): boyut sabittir, yer degisir.

Genisletilmis MBR bolumu kullanicinin duzenledigi bir oge degildir; icindeki
mantiksal bolumlere gore her seferinde yeniden hesaplanir.

## Uygulama sirasi (`restore_with_layout`)

  1. Bolumlerden onceki alan (MBR onyukleme kodu, GRUB'un MBR boslugu)
     yedekten kopyalanir.
  2. Her bolum yeni yerine kopyalanir. **Kucultulen** bolumde yedek salt
     okunur oldugu icin dosya sistemi bellekteki bir yazma katmani
     (`_Overlay`) uzerinde kucultulur, sonra yeni boyut kadari yazilir.
  3. Bolum tablosu hedefin boyutuna gore yeniden yazilir (GPT yedek basligi
     yeni disk sonuna gider).
  4. **Buyutulen** bolumde dosya sistemi hedef uzerinde buyutulur; yalnizca
     yeri degisen bolumde onyukleme sektorundeki bolum konumu duzeltilir.
"""
from __future__ import annotations

import copy
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional

from .clone import CloneError, DubImage, read_backup_info
from .gpt import GPTTable
from .image import BlockDevice, PartitionView
from .mbr import MBRTable
from .ptable import (ALIGN_BYTES, MBR_EXTENDED_TYPES, Partition,
                     PartitionTable, human_size)
from .resize import (_fs_resize, _patch_partition_offset, fs_resize_info)
from ..i18n import tr

Progress = Optional[Callable[[str, int], None]]

FS_KINDS = ("fat", "exfat", "ntfs")      # saf Python'da boyutlandirilabilenler
COPY_CHUNK = 4 * 1024 * 1024
OVERLAY_CHUNK = 64 * 1024


class RestorePlanError(Exception):
    pass


# --------------------------------------------------------------------------
#  Yerlesim
# --------------------------------------------------------------------------
@dataclass
class LayoutPart:
    """Yedekteki bir bolumun eski ve yeni yeri."""
    part: Partition                  # yedekteki tanim (tip, GUID, ad)
    old_start: int
    old_count: int
    new_start: int
    new_count: int
    kind: str = "raw"                # FsResizeInfo.kind
    fs_type: str = ""
    label: str = ""
    min_count: int = 1
    max_count: int = 0               # 0 = sinirsiz
    note: str = ""

    @property
    def index(self) -> int:
        return self.part.index

    @property
    def logical(self) -> bool:
        return self.part.logical

    @property
    def resizable(self) -> bool:
        """Boyutu degistirilebilir mi (ham bolum yalnizca buyuyebilir)."""
        return self.kind in FS_KINDS or self.kind == "raw"

    @property
    def fs_resizable(self) -> bool:
        return self.kind in FS_KINDS

    @property
    def moves(self) -> bool:
        return self.new_start != self.old_start

    @property
    def grows(self) -> bool:
        return self.new_count > self.old_count

    @property
    def shrinks(self) -> bool:
        return self.new_count < self.old_count

    @property
    def new_end(self) -> int:
        return self.new_start + self.new_count - 1

    def clamp(self, count: int) -> int:
        count = max(self.min_count, count)
        if self.max_count:
            count = min(self.max_count, count)
        return count

    def as_partition(self) -> Partition:
        """Yeni yerindeki bolum (harita ve tablo icin kopya)."""
        part = copy.copy(self.part)
        part.start_lba = self.new_start
        part.sector_count = self.new_count
        part.fs_type = self.fs_type
        part.fs_label = self.label
        if part.logical:
            part.ebr_lba = 0          # EBR yeni baslangica gore hesaplanir
        return part


@dataclass
class RestoreLayout:
    """Yedegin hedef diske yerlesim plani."""
    scheme: str                       # 'gpt' | 'mbr'
    sector_size: int
    source_sectors: int
    target_sectors: int
    parts: List[LayoutPart] = field(default_factory=list)
    extended: Optional[Partition] = None      # MBR genisletilmis kapsayici
    gpt_first_usable: int = 0
    gpt_entry_sectors: int = 32

    # -- sinirlar ------------------------------------------------------------
    @property
    def align(self) -> int:
        return max(1, ALIGN_BYTES // self.sector_size)

    def first_usable(self) -> int:
        if self.scheme == "gpt":
            return max(self.gpt_first_usable, 2 + self.gpt_entry_sectors)
        return 1

    def last_usable(self) -> int:
        if self.scheme == "gpt":
            return self.target_sectors - 2 - self.gpt_entry_sectors
        return self.target_sectors - 1

    def align_up(self, lba: int) -> int:
        return -(-lba // self.align) * self.align

    def align_down(self, lba: int) -> int:
        return (lba // self.align) * self.align

    def sorted_parts(self) -> List[LayoutPart]:
        return sorted(self.parts, key=lambda p: (p.new_start, p.index))

    def get(self, index: int) -> LayoutPart:
        for part in self.parts:
            if part.index == index:
                return part
        raise RestorePlanError(tr("{} numarali bolum yok", index))

    def _reserved_before(self, part: LayoutPart) -> int:
        """Bolumun onunde ayrilmasi gereken sektor (mantiksalda EBR)."""
        return self.align if part.logical else 0

    # -- durum ---------------------------------------------------------------
    @property
    def is_identity(self) -> bool:
        """Yerlesim yedektekiyle ayni ve hedef ayni boyutta mi?"""
        return (self.target_sectors == self.source_sectors
                and all(not p.moves and p.new_count == p.old_count
                        for p in self.parts))

    @property
    def changed(self) -> bool:
        return any(p.moves or p.new_count != p.old_count for p in self.parts)

    def required_sectors(self) -> int:
        """En siki yerlesimde hedefin en az kac sektor olmasi gerektigi."""
        trial = self.copy()
        trial.target_sectors = 1 << 62
        trial._pack(0.0)
        end = max((p.new_end for p in trial.parts), default=0)
        tail = (2 + self.gpt_entry_sectors) if self.scheme == "gpt" else 1
        return end + tail

    def validate(self) -> str:
        """Yerlesimdeki ilk hata ("" = gecerli)."""
        if self.target_sectors <= 0:
            return tr("Hedef boyutu bilinmiyor")
        previous_end = self.first_usable() - 1
        for part in self.sorted_parts():
            if part.new_count <= 0:
                return tr("Bolum {}: boyut sifir olamaz", part.index)
            if part.new_count < part.min_count:
                return tr("Bolum {}: {} altina inemez (veri kaybi olurdu)",
                          part.index,
                          human_size(part.min_count * self.sector_size))
            if part.max_count and part.new_count > part.max_count:
                return tr("Bolum {}: dosya sistemi en fazla {} olabilir",
                          part.index,
                          human_size(part.max_count * self.sector_size))
            if not part.resizable and part.new_count != part.old_count:
                return tr("Bolum {}: {} boyutlandirilamaz",
                          part.index, part.fs_type or tr("bu dosya sistemi"))
            if part.new_start - self._reserved_before(part) <= previous_end:
                return tr("Bolum {} onceki bolumle cakisiyor", part.index)
            if part.new_end > self.last_usable():
                return tr("Bolum {} hedef diskin sonunu asiyor "
                          "(hedef {}, gereken en az {})", part.index,
                          human_size(self.target_sectors * self.sector_size),
                          human_size(self.required_sectors()
                                     * self.sector_size))
            previous_end = part.new_end
        if self.scheme == "mbr":
            primaries = [p for p in self.parts if not p.logical]
            if len(primaries) + (1 if self.extended is not None else 0) > 4:
                return tr("MBR en fazla 4 birincil bolum destekler")
            if self.extended is not None:
                logicals = [p for p in self.sorted_parts() if p.logical]
                ext_start = logicals[0].new_start - self.align
                ext_end = logicals[-1].new_end
                for p in primaries:
                    if not (p.new_end < ext_start or p.new_start > ext_end):
                        return tr("Bolum {} mantiksal bolumlerin arasina "
                                  "giremez", p.index)
        return ""

    # -- stratejiler ---------------------------------------------------------
    def copy(self) -> "RestoreLayout":
        clone = copy.copy(self)
        clone.parts = [copy.copy(p) for p in self.parts]
        return clone

    def reset(self) -> None:
        """Yedekteki yerlesime dondurur."""
        for part in self.parts:
            part.new_start, part.new_count = part.old_start, part.old_count

    def retarget(self, target_sectors: int) -> None:
        """Hedef boyutunu degistirir ve yerlesimi ona uydurur.

        Yedekteki yerlesim sigiyorsa oldugu gibi kalir (fazla alan bos kalir);
        sigmiyorsa bolumler **gerektigi kadar** kucultulur.
        """
        self.target_sectors = target_sectors
        self.reset()
        if self.validate():
            self.fit(expand=False)

    def fit(self, expand: bool = True) -> bool:
        """Bolumleri orantili olarak hedefe yayar.

        `expand=False` yalnizca sigdirmak icin kucultur; `True` bos alani da
        bolumlere dagitir. Sigmiyorsa False doner ve yerlesim degismez.
        """
        low, high = 0.0, 1.0
        if expand:
            high = max(1.0, 2.0 * self.target_sectors
                       / max(1, self.source_sectors))
        saved = [(p.new_start, p.new_count) for p in self.parts]
        if not self._pack(0.0):
            for part, (start, count) in zip(self.parts, saved):
                part.new_start, part.new_count = start, count
            return False
        if self._pack(high):
            return True
        for _ in range(48):
            middle = (low + high) / 2
            if self._pack(middle):
                low = middle
            else:
                high = middle
        self._pack(low)
        return True

    def extend_last(self) -> bool:
        """Diskte en sondaki boyutlandirilabilir bolumu bos alana yayar."""
        ordered = self.sorted_parts()
        for part in reversed(ordered):
            if not part.resizable:
                continue
            after = [p for p in ordered if p.new_start > part.new_start]
            upper = (min(p.new_start - self._reserved_before(p)
                         for p in after) - 1 if after
                     else self.last_usable())
            count = upper - part.new_start + 1
            if part.max_count:
                count = min(count, part.max_count)
            if count < part.min_count:
                return False
            part.new_count = count
            return True
        return False

    def _pack(self, factor: float) -> bool:
        """Bolumleri eski sirasiyla arka arkaya dizer; boyut = eski * factor."""
        cursor = self.first_usable()
        first = min((p.old_start - self._reserved_before(p)
                     for p in self.parts), default=cursor)
        cursor = self.align_up(max(cursor, min(first, self.align)))
        for part in sorted(self.parts, key=lambda p: p.old_start):
            cursor += self._reserved_before(part)
            start = self.align_up(cursor)
            if part.resizable:
                count = part.clamp(self.align_down(int(part.old_count * factor)))
                if not part.fs_resizable:
                    count = max(count, part.old_count)
            else:
                count = part.old_count
            part.new_start, part.new_count = start, count
            cursor = start + count
        return cursor - 1 <= self.last_usable()

    def window(self, index: int) -> tuple:
        """Bolumun komsulari arasinda hareket edebilecegi (ilk, son) LBA."""
        part = self.get(index)
        ordered = self.sorted_parts()
        pos = ordered.index(part)
        lower = self.first_usable()
        if pos > 0:
            lower = ordered[pos - 1].new_end + 1
        lower += self._reserved_before(part)
        upper = self.last_usable()
        if pos + 1 < len(ordered):
            nxt = ordered[pos + 1]
            upper = nxt.new_start - self._reserved_before(nxt) - 1
        return lower, upper

    def partitions(self) -> List[Partition]:
        """Haritada gosterilecek bolumler (yeni yerlerinde)."""
        out = [p.as_partition() for p in self.sorted_parts()]
        extended = self._extended_partition()
        if extended is not None:
            out.append(extended)
        return out

    def _extended_partition(self) -> Optional[Partition]:
        if self.extended is None:
            return None
        logicals = [p for p in self.sorted_parts() if p.logical]
        if not logicals:
            return None
        ext = copy.copy(self.extended)
        ext.start_lba = logicals[0].new_start - self.align
        ext.sector_count = logicals[-1].new_end - ext.start_lba + 1
        return ext

    def summary(self) -> List[str]:
        """Degisen bolumlerin tek satirlik dokumu."""
        lines = []
        ss = self.sector_size
        for part in self.sorted_parts():
            if part.new_count != part.old_count:
                lines.append(tr("Bolum {}: {} -> {}", part.index,
                                human_size(part.old_count * ss),
                                human_size(part.new_count * ss)))
            elif part.moves:
                lines.append(tr("Bolum {}: yeri degisiyor", part.index))
        return lines


def build_layout(image: BlockDevice, table: PartitionTable) -> RestoreLayout:
    """Yedek goruntusunun tablosundan yerlesim cikarir (hedef = kaynak).

    Dosya sistemi sinirlari yedegin icinden okunur; NTFS'te `$Bitmap`
    taranir, yani buyuk yedekte birkac saniye surebilir — arka planda
    cagrilir.
    """
    from .fsdetect import detect

    layout = RestoreLayout(scheme=table.scheme,
                           sector_size=image.sector_size,
                           source_sectors=image.sector_count,
                           target_sectors=image.sector_count)
    if isinstance(table, GPTTable):
        layout.gpt_first_usable = table._first_usable
        layout.gpt_entry_sectors = table.entry_sectors
    for part in table.sorted_partitions():
        if not part.logical and part.scheme == "mbr" and \
                part.type_id in MBR_EXTENDED_TYPES:
            layout.extended = copy.copy(part)
            continue
        view = PartitionView(image, part.start_lba, part.sector_count)
        try:
            found = detect(view)
            fs_type, label = found.fs_type, found.label
        except Exception:                             # noqa: BLE001
            fs_type, label = "", ""
        info = fs_resize_info(view, fs_type)
        item = LayoutPart(part=copy.copy(part), old_start=part.start_lba,
                          old_count=part.sector_count,
                          new_start=part.start_lba,
                          new_count=part.sector_count, kind=info.kind,
                          fs_type=fs_type, label=label, note=info.note)
        if info.kind in FS_KINDS:
            item.min_count = max(1, info.min_sectors)
            item.max_count = info.max_sectors
        elif info.kind == "raw":
            item.min_count = part.sector_count   # icerigi bilinmiyor
        else:
            item.min_count = item.max_count = part.sector_count
        layout.parts.append(item)
    return layout


def _read_table(device: BlockDevice) -> Optional[PartitionTable]:
    if GPTTable.is_present(device):
        return GPTTable.read(device)
    if MBRTable.is_present(device):
        return MBRTable.read(device)
    return None


def read_layout(src_path: str) -> Optional[RestoreLayout]:
    """`.dub` yedeginin yerlesimi; bolum tablosu yoksa None."""
    image = DubImage(src_path)
    try:
        table = _read_table(image)
        if table is None or not table.partitions:
            return None
        return build_layout(image, table)
    finally:
        image.close()


# --------------------------------------------------------------------------
#  Bellekte yazma katmani
# --------------------------------------------------------------------------
class _Overlay(BlockDevice):
    """Salt okunur bir aygitin ustunde bellekte duran yazma katmani.

    Kucultme, dosya sisteminin meta verisini (FAT/bitmap, NTFS'te sondan
    tasinan kumeler) yeniden yazar. Yedek dosyasi salt okunurdur; yazilar
    burada tutulur ve okumada yedegin uzerine bindirilir.
    """

    def __init__(self, base: BlockDevice):
        self._base = base
        self.sector_size = base.sector_size
        self._chunks: Dict[int, bytearray] = {}

    @property
    def sector_count(self) -> int:
        return self._base.sector_count

    @property
    def overlay_bytes(self) -> int:
        return len(self._chunks) * OVERLAY_CHUNK

    def _chunk(self, no: int) -> bytearray:
        data = self._chunks.get(no)
        if data is None:
            start = no * OVERLAY_CHUNK
            length = min(OVERLAY_CHUNK, self.size - start)
            data = bytearray(self._base.read(start, length))
            self._chunks[no] = data
        return data

    def read(self, offset: int, length: int) -> bytes:
        if offset + length > self.size:
            raise RestorePlanError(tr("Okuma bolum sinirini asiyor"))
        out = bytearray()
        pos = offset
        end = offset + length
        while pos < end:
            no, inner = divmod(pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, end - pos)
            data = self._chunks.get(no)
            if data is not None:
                out += data[inner:inner + n]
            else:
                # yazilmamis parcalar tek okumada birlestirilir
                run = n
                while pos + run < end and \
                        (pos + run) // OVERLAY_CHUNK not in self._chunks:
                    run += min(OVERLAY_CHUNK, end - pos - run)
                out += self._base.read(pos, run)
                n = run
            pos += n
        return bytes(out)

    def write(self, offset: int, data: bytes) -> None:
        if offset + len(data) > self.size:
            raise RestorePlanError(tr("Yazma bolum sinirini asiyor"))
        pos = 0
        while pos < len(data):
            no, inner = divmod(offset + pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, len(data) - pos)
            self._chunk(no)[inner:inner + n] = data[pos:pos + n]
            pos += n


# --------------------------------------------------------------------------
#  Uygulama
# --------------------------------------------------------------------------
def _copy_region(src: BlockDevice, src_lba: int, dst: BlockDevice,
                 dst_lba: int, count: int, tick: Callable[[int], None]) -> None:
    """Sektorleri kopyalar; bos (sifir) parcada hedef zaten sifirsa yazmaz."""
    ss = src.sector_size
    step = max(1, COPY_CHUNK // ss)
    pos = 0
    while pos < count:
        n = min(step, count - pos)
        data = src.read_sectors(src_lba + pos, n)
        if data.strip(b"\x00") or \
                dst.read_sectors(dst_lba + pos, n).strip(b"\x00"):
            dst.write_sectors(dst_lba + pos, data)
        pos += n
        tick(n)


def restore_with_layout(src_path: str, device: BlockDevice,
                        layout: RestoreLayout,
                        progress: Progress = None):
    """`.dub` disk yedegini `layout` yerlesimiyle `device` uzerine yazar."""
    def report(message: str, percent: int) -> None:
        if progress:
            progress(message, max(0, min(100, percent)))

    info = read_backup_info(src_path)
    if device.sector_count != layout.target_sectors:
        raise RestorePlanError(
            tr("Yerlesim baska bir hedef boyutu icin hazirlanmis; yenileyin"))
    if getattr(device, "readonly", False):
        raise CloneError(tr("Hedef salt okunur"))
    problem = layout.validate()
    if problem:
        raise RestorePlanError(problem)

    src = DubImage(src_path)
    try:
        if src.sector_size != device.sector_size:
            raise RestorePlanError(
                tr("Sektor boyutu farkli: yedek {}, hedef {}",
                   src.sector_size, device.sector_size))
        table = _read_table(src)
        if table is None or table.scheme != layout.scheme:
            raise RestorePlanError(tr("Yedegin bolum tablosu okunamadi"))

        ss = device.sector_size
        total = sum(min(p.old_count, p.new_count) for p in layout.parts) or 1
        done = [0]

        def tick(n: int) -> None:
            done[0] += n
            report(tr("Geri yukleniyor... {} / {}",
                      human_size(done[0] * ss), human_size(total * ss)),
                   5 + int(85 * done[0] / total))

        # 1) bolumlerden onceki alan: onyukleme kodu ve MBR boslugu
        report(tr("Geri yukleme baslatiliyor..."), 1)
        head = min([p.old_start - layout._reserved_before(p)
                    for p in layout.parts]
                   + [p.new_start - layout._reserved_before(p)
                      for p in layout.parts])
        _copy_region(src, 0, device, 0, max(1, head), lambda n: None)
        if layout.scheme == "mbr":
            # Hedefte eskiden GPT varsa yedek basligi diskin sonunda kalir;
            # bazi sistemler onu bulup MBR'yi yok sayar.
            last = device.sector_count - 1
            if device.read_sectors(last)[:8] == b"EFI PART":
                device.write_sectors(last, b"\x00" * ss)

        # 2) bolumler yeni yerlerine
        for part in layout.sorted_parts():
            source: BlockDevice = PartitionView(src, part.old_start,
                                                part.old_count)
            start = 0
            if part.shrinks and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi kucultuluyor...",
                          part.index), 5 + int(85 * done[0] / total))
                overlay = _Overlay(source)
                _fs_resize(overlay, 0, part.new_count, part.kind,
                           part.new_start, span=part.old_count)
                source = overlay
            _copy_region(source, start, device, part.new_start,
                         min(part.old_count, part.new_count), tick)

        # 3) bolum tablosu hedefin boyutuna gore
        report(tr("Bolum tablosu yaziliyor..."), 91)
        if layout.scheme == "gpt":
            new_table = GPTTable(device)
            new_table.disk_guid = table.disk_guid
            new_table.entry_count = table.entry_count
            new_table.entry_size = table.entry_size
            new_table._first_usable = layout.first_usable()
        else:
            new_table = MBRTable(device)
            new_table.bootcode = table.bootcode
            new_table.disk_signature = table.disk_signature
        new_table.partitions = layout.partitions()
        new_table.write()

        # 4) buyutme ve konum duzeltme hedefin uzerinde
        for part in layout.sorted_parts():
            if part.grows and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi buyutuluyor...",
                          part.index), 93)
                _fs_resize(device, part.new_start, part.new_count, part.kind,
                           part.new_start)
            elif part.moves and not part.shrinks:
                _patch_partition_offset(device, part.new_start,
                                        part.new_count)
        flush = getattr(device, "flush", None)
        if flush:
            flush()
    finally:
        src.close()
    report(tr("Tamamlandi"), 100)
    return info

toolUseResult.content:
"""Yedegi hedef diske **yeni bir bolum yerlesimiyle** geri yukleme.

## Neden

Duz geri yukleme (`clone.restore`) yedegi bayt bayt yazar: hedef yedekten
kucukse reddedilir, buyukse fazlasi bos kalir ve GPT'nin yedek basligi eski
disk sonunda kalir. DiskGenius'un "Bolumleri Yonet" dugmesi ise yedekteki
bolumleri hedef diske **yeniden yerlestirir**: bolumler buyutulup
kucultulebilir, kaydirilabilir; dosya sistemi yeni boyuta getirilir.

## Yerlesim

`RestoreLayout` yedekteki her bolum icin eski ve yeni (baslangic, sektor)
ciftini ve dosya sisteminin sinirlarini tasir. Sinirlar `resize.fs_resize_info`
ile **yedegin icinden** okunur:

  * FAT / exFAT / NTFS: en az = verinin gerektirdigi, en cok = FS siniri.
  * Dosya sistemi tanimlanamayan bolum ("ham"): **kucultulmez** (icerigini
    bilmiyoruz; BitLocker da ham gorunur), buyutulebilir ama eklenen alan
    kullanilmaz.
  * Boyutlandirilamayan dosya sistemi (ext vb.): boyut sabittir, yer degisir.

Genisletilmis MBR bolumu kullanicinin duzenledigi bir oge degildir; icindeki
mantiksal bolumlere gore her seferinde yeniden hesaplanir.

## Uygulama sirasi (`restore_with_layout`)

  1. Bolumlerden onceki alan (MBR onyukleme kodu, GRUB'un MBR boslugu)
     yedekten kopyalanir.
  2. Her bolum yeni yerine kopyalanir. **Kucultulen** bolumde yedek salt
     okunur oldugu icin dosya sistemi bellekteki bir yazma katmani
     (`_Overlay`) uzerinde kucultulur, sonra yeni boyut kadari yazilir.
  3. Bolum tablosu hedefin boyutuna gore yeniden yazilir (GPT yedek basligi
     yeni disk sonuna gider).
  4. **Buyutulen** bolumde dosya sistemi hedef uzerinde buyutulur; yalnizca
     yeri degisen bolumde onyukleme sektorundeki bolum konumu duzeltilir.
"""
from __future__ import annotations

import copy
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional

from .clone import CloneError, DubImage, read_backup_info
from .gpt import GPTTable
from .image import BlockDevice, PartitionView
from .mbr import MBRTable
from .ptable import (ALIGN_BYTES, MBR_EXTENDED_TYPES, Partition,
                     PartitionTable, human_size)
from .resize import (_fs_resize, _patch_partition_offset, fs_resize_info)
from ..i18n import tr

Progress = Optional[Callable[[str, int], None]]

FS_KINDS = ("fat", "exfat", "ntfs")      # saf Python'da boyutlandirilabilenler
COPY_CHUNK = 4 * 1024 * 1024
OVERLAY_CHUNK = 64 * 1024


class RestorePlanError(Exception):
    pass


# --------------------------------------------------------------------------
#  Yerlesim
# --------------------------------------------------------------------------
@dataclass
class LayoutPart:
    """Yedekteki bir bolumun eski ve yeni yeri."""
    part: Partition                  # yedekteki tanim (tip, GUID, ad)
    old_start: int
    old_count: int
    new_start: int
    new_count: int
    kind: str = "raw"                # FsResizeInfo.kind
    fs_type: str = ""
    label: str = ""
    min_count: int = 1
    max_count: int = 0               # 0 = sinirsiz
    note: str = ""

    @property
    def index(self) -> int:
        return self.part.index

    @property
    def logical(self) -> bool:
        return self.part.logical

    @property
    def resizable(self) -> bool:
        """Boyutu degistirilebilir mi (ham bolum yalnizca buyuyebilir)."""
        return self.kind in FS_KINDS or self.kind == "raw"

    @property
    def fs_resizable(self) -> bool:
        return self.kind in FS_KINDS

    @property
    def moves(self) -> bool:
        return self.new_start != self.old_start

    @property
    def grows(self) -> bool:
        return self.new_count > self.old_count

    @property
    def shrinks(self) -> bool:
        return self.new_count < self.old_count

    @property
    def new_end(self) -> int:
        return self.new_start + self.new_count - 1

    def clamp(self, count: int) -> int:
        count = max(self.min_count, count)
        if self.max_count:
            count = min(self.max_count, count)
        return count

    def as_partition(self) -> Partition:
        """Yeni yerindeki bolum (harita ve tablo icin kopya)."""
        part = copy.copy(self.part)
        part.start_lba = self.new_start
        part.sector_count = self.new_count
        part.fs_type = self.fs_type
        part.fs_label = self.label
        if part.logical:
            part.ebr_lba = 0          # EBR yeni baslangica gore hesaplanir
        return part


@dataclass
class RestoreLayout:
    """Yedegin hedef diske yerlesim plani."""
    scheme: str                       # 'gpt' | 'mbr'
    sector_size: int
    source_sectors: int
    target_sectors: int
    parts: List[LayoutPart] = field(default_factory=list)
    extended: Optional[Partition] = None      # MBR genisletilmis kapsayici
    gpt_first_usable: int = 0
    gpt_entry_sectors: int = 32

    # -- sinirlar ------------------------------------------------------------
    @property
    def align(self) -> int:
        return max(1, ALIGN_BYTES // self.sector_size)

    def first_usable(self) -> int:
        if self.scheme == "gpt":
            return max(self.gpt_first_usable, 2 + self.gpt_entry_sectors)
        return 1

    def last_usable(self) -> int:
        if self.scheme == "gpt":
            return self.target_sectors - 2 - self.gpt_entry_sectors
        return self.target_sectors - 1

    def align_up(self, lba: int) -> int:
        return -(-lba // self.align) * self.align

    def align_down(self, lba: int) -> int:
        return (lba // self.align) * self.align

    def sorted_parts(self) -> List[LayoutPart]:
        return sorted(self.parts, key=lambda p: (p.new_start, p.index))

    def get(self, index: int) -> LayoutPart:
        for part in self.parts:
            if part.index == index:
                return part
        raise RestorePlanError(tr("{} numarali bolum yok", index))

    def _reserved_before(self, part: LayoutPart) -> int:
        """Bolumun onunde ayrilmasi gereken sektor (mantiksalda EBR)."""
        return self.align if part.logical else 0

    # -- durum ---------------------------------------------------------------
    @property
    def is_identity(self) -> bool:
        """Yerlesim yedektekiyle ayni ve hedef ayni boyutta mi?"""
        return (self.target_sectors == self.source_sectors
                and all(not p.moves and p.new_count == p.old_count
                        for p in self.parts))

    @property
    def changed(self) -> bool:
        return any(p.moves or p.new_count != p.old_count for p in self.parts)

    def required_sectors(self) -> int:
        """En siki yerlesimde hedefin en az kac sektor olmasi gerektigi."""
        trial = self.copy()
        trial.target_sectors = 1 << 62
        trial._pack(0.0)
        end = max((p.new_end for p in trial.parts), default=0)
        tail = (2 + self.gpt_entry_sectors) if self.scheme == "gpt" else 1
        return end + tail

    def validate(self) -> str:
        """Yerlesimdeki ilk hata ("" = gecerli)."""
        if self.target_sectors <= 0:
            return tr("Hedef boyutu bilinmiyor")
        previous_end = self.first_usable() - 1
        for part in self.sorted_parts():
            if part.new_count <= 0:
                return tr("Bolum {}: boyut sifir olamaz", part.index)
            if part.new_count < part.min_count:
                return tr("Bolum {}: {} altina inemez (veri kaybi olurdu)",
                          part.index,
                          human_size(part.min_count * self.sector_size))
            if part.max_count and part.new_count > part.max_count:
                return tr("Bolum {}: dosya sistemi en fazla {} olabilir",
                          part.index,
                          human_size(part.max_count * self.sector_size))
            if not part.resizable and part.new_count != part.old_count:
                return tr("Bolum {}: {} boyutlandirilamaz",
                          part.index, part.fs_type or tr("bu dosya sistemi"))
            if part.new_start - self._reserved_before(part) <= previous_end:
                return tr("Bolum {} onceki bolumle cakisiyor", part.index)
            if part.new_end > self.last_usable():
                return tr("Bolum {} hedef diskin sonunu asiyor "
                          "(hedef {}, gereken en az {})", part.index,
                          human_size(self.target_sectors * self.sector_size),
                          human_size(self.required_sectors()
                                     * self.sector_size))
            previous_end = part.new_end
        if self.scheme == "mbr":
            primaries = [p for p in self.parts if not p.logical]
            if len(primaries) + (1 if self.extended is not None else 0) > 4:
                return tr("MBR en fazla 4 birincil bolum destekler")
            if self.extended is not None:
                logicals = [p for p in self.sorted_parts() if p.logical]
                ext_start = logicals[0].new_start - self.align
                ext_end = logicals[-1].new_end
                for p in primaries:
                    if not (p.new_end < ext_start or p.new_start > ext_end):
                        return tr("Bolum {} mantiksal bolumlerin arasina "
                                  "giremez", p.index)
        return ""

    # -- stratejiler ---------------------------------------------------------
    def copy(self) -> "RestoreLayout":
        clone = copy.copy(self)
        clone.parts = [copy.copy(p) for p in self.parts]
        return clone

    def reset(self) -> None:
        """Yedekteki yerlesime dondurur."""
        for part in self.parts:
            part.new_start, part.new_count = part.old_start, part.old_count

    def retarget(self, target_sectors: int) -> None:
        """Hedef boyutunu degistirir ve yerlesimi ona uydurur.

        Yedekteki yerlesim sigiyorsa oldugu gibi kalir (fazla alan bos kalir);
        sigmiyorsa bolumler **gerektigi kadar** kucultulur.
        """
        self.target_sectors = target_sectors
        self.reset()
        if self.validate():
            self.fit(expand=False)

    def fit(self, expand: bool = True) -> bool:
        """Bolumleri orantili olarak hedefe yayar.

        `expand=False` yalnizca sigdirmak icin kucultur; `True` bos alani da
        bolumlere dagitir. Sigmiyorsa False doner ve yerlesim degismez.
        """
        low, high = 0.0, 1.0
        if expand:
            high = max(1.0, 2.0 * self.target_sectors
                       / max(1, self.source_sectors))
        saved = [(p.new_start, p.new_count) for p in self.parts]
        if not self._pack(0.0):
            for part, (start, count) in zip(self.parts, saved):
                part.new_start, part.new_count = start, count
            return False
        if self._pack(high):
            return True
        for _ in range(48):
            middle = (low + high) / 2
            if self._pack(middle):
                low = middle
            else:
                high = middle
        self._pack(low)
        return True

    def extend_last(self) -> bool:
        """Diskte en sondaki boyutlandirilabilir bolumu bos alana yayar."""
        ordered = self.sorted_parts()
        for part in reversed(ordered):
            if not part.resizable:
                continue
            after = [p for p in ordered if p.new_start > part.new_start]
            upper = (min(p.new_start - self._reserved_before(p)
                         for p in after) - 1 if after
                     else self.last_usable())
            count = upper - part.new_start + 1
            if part.max_count:
                count = min(count, part.max_count)
            if count < part.min_count:
                return False
            part.new_count = count
            return True
        return False

    def _pack(self, factor: float) -> bool:
        """Bolumleri eski sirasiyla arka arkaya dizer; boyut = eski * factor."""
        cursor = self.first_usable()
        first = min((p.old_start - self._reserved_before(p)
                     for p in self.parts), default=cursor)
        cursor = self.align_up(max(cursor, min(first, self.align)))
        for part in sorted(self.parts, key=lambda p: p.old_start):
            cursor += self._reserved_before(part)
            start = self.align_up(cursor)
            if part.resizable:
                count = part.clamp(self.align_down(int(part.old_count * factor)))
                if not part.fs_resizable:
                    count = max(count, part.old_count)
            else:
                count = part.old_count
            part.new_start, part.new_count = start, count
            cursor = start + count
        return cursor - 1 <= self.last_usable()

    def window(self, index: int) -> tuple:
        """Bolumun komsulari arasinda hareket edebilecegi (ilk, son) LBA."""
        part = self.get(index)
        ordered = self.sorted_parts()
        pos = ordered.index(part)
        lower = self.first_usable()
        if pos > 0:
            lower = ordered[pos - 1].new_end + 1
        lower += self._reserved_before(part)
        upper = self.last_usable()
        if pos + 1 < len(ordered):
            nxt = ordered[pos + 1]
            upper = nxt.new_start - self._reserved_before(nxt) - 1
        return lower, upper

    def partitions(self) -> List[Partition]:
        """Haritada gosterilecek bolumler (yeni yerlerinde)."""
        out = [p.as_partition() for p in self.sorted_parts()]
        extended = self._extended_partition()
        if extended is not None:
            out.append(extended)
        return out

    def _extended_partition(self) -> Optional[Partition]:
        if self.extended is None:
            return None
        logicals = [p for p in self.sorted_parts() if p.logical]
        if not logicals:
            return None
        ext = copy.copy(self.extended)
        ext.start_lba = logicals[0].new_start - self.align
        ext.sector_count = logicals[-1].new_end - ext.start_lba + 1
        return ext

    def summary(self) -> List[str]:
        """Degisen bolumlerin tek satirlik dokumu."""
        lines = []
        ss = self.sector_size
        for part in self.sorted_parts():
            if part.new_count != part.old_count:
                lines.append(tr("Bolum {}: {} -> {}", part.index,
                                human_size(part.old_count * ss),
                                human_size(part.new_count * ss)))
            elif part.moves:
                lines.append(tr("Bolum {}: yeri degisiyor", part.index))
        return lines


def build_layout(image: BlockDevice, table: PartitionTable) -> RestoreLayout:
    """Yedek goruntusunun tablosundan yerlesim cikarir (hedef = kaynak).

    Dosya sistemi sinirlari yedegin icinden okunur; NTFS'te `$Bitmap`
    taranir, yani buyuk yedekte birkac saniye surebilir — arka planda
    cagrilir.
    """
    from .fsdetect import detect

    layout = RestoreLayout(scheme=table.scheme,
                           sector_size=image.sector_size,
                           source_sectors=image.sector_count,
                           target_sectors=image.sector_count)
    if isinstance(table, GPTTable):
        layout.gpt_first_usable = table._first_usable
        layout.gpt_entry_sectors = table.entry_sectors
    for part in table.sorted_partitions():
        if not part.logical and part.scheme == "mbr" and \
                part.type_id in MBR_EXTENDED_TYPES:
            layout.extended = copy.copy(part)
            continue
        view = PartitionView(image, part.start_lba, part.sector_count)
        try:
            found = detect(view)
            fs_type, label = found.fs_type, found.label
        except Exception:                             # noqa: BLE001
            fs_type, label = "", ""
        info = fs_resize_info(view, fs_type)
        item = LayoutPart(part=copy.copy(part), old_start=part.start_lba,
                          old_count=part.sector_count,
                          new_start=part.start_lba,
                          new_count=part.sector_count, kind=info.kind,
                          fs_type=fs_type, label=label, note=info.note)
        if info.kind in FS_KINDS:
            item.min_count = max(1, info.min_sectors)
            item.max_count = info.max_sectors
        elif info.kind == "raw":
            item.min_count = part.sector_count   # icerigi bilinmiyor
        else:
            item.min_count = item.max_count = part.sector_count
        layout.parts.append(item)
    return layout


def _read_table(device: BlockDevice) -> Optional[PartitionTable]:
    if GPTTable.is_present(device):
        return GPTTable.read(device)
    if MBRTable.is_present(device):
        return MBRTable.read(device)
    return None


def read_layout(src_path: str) -> Optional[RestoreLayout]:
    """`.dub` yedeginin yerlesimi; bolum tablosu yoksa None."""
    image = DubImage(src_path)
    try:
        table = _read_table(image)
        if table is None or not table.partitions:
            return None
        return build_layout(image, table)
    finally:
        image.close()


# --------------------------------------------------------------------------
#  Bellekte yazma katmani
# --------------------------------------------------------------------------
class _Overlay(BlockDevice):
    """Salt okunur bir aygitin ustunde bellekte duran yazma katmani.

    Kucultme, dosya sisteminin meta verisini (FAT/bitmap, NTFS'te sondan
    tasinan kumeler) yeniden yazar. Yedek dosyasi salt okunurdur; yazilar
    burada tutulur ve okumada yedegin uzerine bindirilir.
    """

    def __init__(self, base: BlockDevice):
        self._base = base
        self.sector_size = base.sector_size
        self._chunks: Dict[int, bytearray] = {}

    @property
    def sector_count(self) -> int:
        return self._base.sector_count

    @property
    def overlay_bytes(self) -> int:
        return len(self._chunks) * OVERLAY_CHUNK

    def _chunk(self, no: int) -> bytearray:
        data = self._chunks.get(no)
        if data is None:
            start = no * OVERLAY_CHUNK
            length = min(OVERLAY_CHUNK, self.size - start)
            data = bytearray(self._base.read(start, length))
            self._chunks[no] = data
        return data

    def read(self, offset: int, length: int) -> bytes:
        if offset + length > self.size:
            raise RestorePlanError(tr("Okuma bolum sinirini asiyor"))
        out = bytearray()
        pos = offset
        end = offset + length
        while pos < end:
            no, inner = divmod(pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, end - pos)
            data = self._chunks.get(no)
            if data is not None:
                out += data[inner:inner + n]
            else:
                # yazilmamis parcalar tek okumada birlestirilir
                run = n
                while pos + run < end and \
                        (pos + run) // OVERLAY_CHUNK not in self._chunks:
                    run += min(OVERLAY_CHUNK, end - pos - run)
                out += self._base.read(pos, run)
                n = run
            pos += n
        return bytes(out)

    def write(self, offset: int, data: bytes) -> None:
        if offset + len(data) > self.size:
            raise RestorePlanError(tr("Yazma bolum sinirini asiyor"))
        pos = 0
        while pos < len(data):
            no, inner = divmod(offset + pos, OVERLAY_CHUNK)
            n = min(OVERLAY_CHUNK - inner, len(data) - pos)
            self._chunk(no)[inner:inner + n] = data[pos:pos + n]
            pos += n


# --------------------------------------------------------------------------
#  Uygulama
# --------------------------------------------------------------------------
def _copy_region(src: BlockDevice, src_lba: int, dst: BlockDevice,
                 dst_lba: int, count: int, tick: Callable[[int], None]) -> None:
    """Sektorleri kopyalar; bos (sifir) parcada hedef zaten sifirsa yazmaz."""
    ss = src.sector_size
    step = max(1, COPY_CHUNK // ss)
    pos = 0
    while pos < count:
        n = min(step, count - pos)
        data = src.read_sectors(src_lba + pos, n)
        if data.strip(b"\x00") or \
                dst.read_sectors(dst_lba + pos, n).strip(b"\x00"):
            dst.write_sectors(dst_lba + pos, data)
        pos += n
        tick(n)


def restore_with_layout(src_path: str, device: BlockDevice,
                        layout: RestoreLayout,
                        progress: Progress = None):
    """`.dub` disk yedegini `layout` yerlesimiyle `device` uzerine yazar."""
    def report(message: str, percent: int) -> None:
        if progress:
            progress(message, max(0, min(100, percent)))

    info = read_backup_info(src_path)
    if device.sector_count != layout.target_sectors:
        raise RestorePlanError(
            tr("Yerlesim baska bir hedef boyutu icin hazirlanmis; yenileyin"))
    if getattr(device, "readonly", False):
        raise CloneError(tr("Hedef salt okunur"))
    problem = layout.validate()
    if problem:
        raise RestorePlanError(problem)

    src = DubImage(src_path)
    try:
        if src.sector_size != device.sector_size:
            raise RestorePlanError(
                tr("Sektor boyutu farkli: yedek {}, hedef {}",
                   src.sector_size, device.sector_size))
        table = _read_table(src)
        if table is None or table.scheme != layout.scheme:
            raise RestorePlanError(tr("Yedegin bolum tablosu okunamadi"))

        ss = device.sector_size
        total = sum(min(p.old_count, p.new_count) for p in layout.parts) or 1
        done = [0]

        def tick(n: int) -> None:
            done[0] += n
            report(tr("Geri yukleniyor... {} / {}",
                      human_size(done[0] * ss), human_size(total * ss)),
                   5 + int(85 * done[0] / total))

        # 1) bolumlerden onceki alan: onyukleme kodu ve MBR boslugu
        report(tr("Geri yukleme baslatiliyor..."), 1)
        head = min([p.old_start - layout._reserved_before(p)
                    for p in layout.parts]
                   + [p.new_start - layout._reserved_before(p)
                      for p in layout.parts])
        _copy_region(src, 0, device, 0, max(1, head), lambda n: None)
        if layout.scheme == "mbr":
            # Hedefte eskiden GPT varsa yedek basligi diskin sonunda kalir;
            # bazi sistemler onu bulup MBR'yi yok sayar.
            last = device.sector_count - 1
            if device.read_sectors(last)[:8] == b"EFI PART":
                device.write_sectors(last, b"\x00" * ss)

        # 2) bolumler yeni yerlerine
        for part in layout.sorted_parts():
            source: BlockDevice = PartitionView(src, part.old_start,
                                                part.old_count)
            start = 0
            if part.shrinks and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi kucultuluyor...",
                          part.index), 5 + int(85 * done[0] / total))
                overlay = _Overlay(source)
                _fs_resize(overlay, 0, part.new_count, part.kind,
                           part.new_start, span=part.old_count)
                source = overlay
            _copy_region(source, start, device, part.new_start,
                         min(part.old_count, part.new_count), tick)

        # 3) bolum tablosu hedefin boyutuna gore
        report(tr("Bolum tablosu yaziliyor..."), 91)
        if layout.scheme == "gpt":
            new_table = GPTTable(device)
            new_table.disk_guid = table.disk_guid
            new_table.entry_count = table.entry_count
            new_table.entry_size = table.entry_size
            new_table._first_usable = layout.first_usable()
        else:
            new_table = MBRTable(device)
            new_table.bootcode = table.bootcode
            new_table.disk_signature = table.disk_signature
        new_table.partitions = layout.partitions()
        new_table.write()

        # 4) buyutme ve konum duzeltme hedefin uzerinde
        for part in layout.sorted_parts():
            if part.grows and part.fs_resizable:
                report(tr("Bolum {}: dosya sistemi buyutuluyor...",
                          part.index), 93)
                _fs_resize(device, part.new_start, part.new_count, part.kind,
                           part.new_start)
            elif part.moves and not part.shrinks:
                _patch_partition_offset(device, part.new_start,
                                        part.new_count)
        flush = getattr(device, "flush", None)
        if flush:
            flush()
    finally:
        src.close()
    report(tr("Tamamlandi"), 100)
    return info

